sp_widget.client_script:
api.controller = function($scope, $window, $timeout, spUtil, $location) {
  var c = this;

  // ── Error handling ──────────────────────────────
  if (c.data.error) {
    spUtil.addErrorMessage(c.data.error);
  }

  // ── Carousel state ──────────────────────────────
  c.currentIndex = 0;
  c.visibleCount = 3;   // cards visible at once

  // ── Responsive: update visibleCount on resize ──
  function updateVisible() {
    var w = $window.innerWidth;
    if      (w <= 600)  c.visibleCount = 1;
    else if (w <= 900)  c.visibleCount = 2;
    else                c.visibleCount = 3;

    // Clamp currentIndex so it never overflows
    var max = Math.max(0, (c.data.programs || []).length - c.visibleCount);
    if (c.currentIndex > max) c.currentIndex = max;

    // Update card widths
    setCardWidths();
  }

  // ── Set card widths dynamically ─────────────────
  function setCardWidths() {
    $timeout(function() {
      var wrap = document.querySelector('.gp-carousel-track-wrap');
      if (!wrap) return;
      var gap        = 20;
      var totalGaps  = (c.visibleCount - 1) * gap;
      var cardWidth  = (wrap.clientWidth - totalGaps) / c.visibleCount;
      var cards      = document.querySelectorAll('.gp-card');
      for (var i = 0; i < cards.length; i++) {
        cards[i].style.width    = cardWidth + 'px';
        cards[i].style.minWidth = cardWidth + 'px';
      }
    }, 50);
  }

  // ── Offset calculation for transform ────────────
  c.offsetPct = function() {
    var wrap = document.querySelector('.gp-carousel-track-wrap');
    if (!wrap) return 0;
    var gap       = 20;
    var cardWidth = (wrap.clientWidth - (c.visibleCount - 1) * gap) / c.visibleCount;
    var slideW    = cardWidth + gap;
    // Return pixel offset as % of track-wrap width
    return (c.currentIndex * slideW) / wrap.clientWidth * 100;
  };

  // ── Navigation ──────────────────────────────────
  c.scrollLeft = function() {
    if (c.currentIndex <= 0) return;
    c.currentIndex -= c.visibleCount;
    if (c.currentIndex < 0) c.currentIndex = 0;
  };

  c.scrollRight = function() {
    var max = (c.data.programs || []).length - c.visibleCount;
    if (c.currentIndex >= max) return;
    c.currentIndex += c.visibleCount;
    if (c.currentIndex > max) c.currentIndex = max;
  };

  // ── End index label ─────────────────────────────
  c.endIndex = function() {
    return Math.min(
      c.currentIndex + c.visibleCount,
      (c.data.programs || []).length
    );
  };

  // ── Dot indicators ──────────────────────────────
  c.dotCount = function() {
    return Math.ceil((c.data.programs || []).length / c.visibleCount);
  };

  c.dots = function() {
    return new Array(c.dotCount());
  };

  c.activeDot = function() {
    return Math.floor(c.currentIndex / c.visibleCount);
  };

  c.goToDot = function(dotIndex) {
    var target = dotIndex * c.visibleCount;
    var max    = (c.data.programs || []).length - c.visibleCount;
    c.currentIndex = Math.min(target, max);
  };

  // ── Detail navigation ───────────────────────────
  c.viewDetails = function(program) {
  if (!program || !program.sys_id) return;

  // Use $location to change the URL parameters safely
  $location.search({
    id: 'published_program_detail',
    sys_id: program.sys_id
  });
};

  // ── Touch / swipe support ───────────────────────
  var touchStartX = 0;

  $timeout(function() {
    var track = document.querySelector('.gp-carousel-track-wrap');
    if (!track) return;

    track.addEventListener('touchstart', function(e) {
      touchStartX = e.touches[0].clientX;
    }, { passive: true });

    track.addEventListener('touchend', function(e) {
      var diff = touchStartX - e.changedTouches[0].clientX;
      if (Math.abs(diff) < 40) return;   // ignore tiny swipes
      if (diff > 0) c.scrollRight();
      else          c.scrollLeft();
      $scope.$apply();
    }, { passive: true });
  }, 300);

  // ── Window resize listener ───────────────────────
  angular.element($window).on('resize', function() {
    updateVisible();
    $scope.$apply();
  });

  // ── Init ────────────────────────────────────────
  $timeout(function() {
    updateVisible();
  }, 100);

};

sp_widget.css:
/* ── Reset ── */
.gp-section *,
.gp-section *::before,
.gp-section *::after { box-sizing: border-box; margin: 0; padding: 0; }

/* ── Section ── */
.gp-section {
  font-family: 'Inter', 'Segoe UI', sans-serif;
  background: #f4f5f9;
  padding: 56px 0 64px;
  width: calc(100% + 30px);
  margin-left: -15px;
}

.gp-inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 48px;
}

/* ════════════════════════════════════════════════
   HEADER
════════════════════════════════════════════════ */
.gp-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}

.gp-header__badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: rgba(84,67,173,0.08);
  border: 1px solid rgba(84,67,173,0.18);
  color: #5443ad;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 100px;
  margin-bottom: 14px;
}

.gp-header__dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #5443ad;
  animation: gpDotPulse 2s ease-in-out infinite;
}

@keyframes gpDotPulse {
  0%,100% { opacity: 1; transform: scale(1); }
  50%      { opacity: 0.4; transform: scale(1.5); }
}

.gp-title {
  font-size: clamp(20px, 2.2vw, 28px);
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin-bottom: 10px;
}

.gp-subtitle {
  font-size: 13.5px;
  color: #64748b;
  line-height: 1.7;
  max-width: 520px;
}

/* Nav buttons */
.gp-header__right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  padding-bottom: 4px;
}

.gp-nav-btn {
  width: 38px; height: 38px;
  border-radius: 10px;
  border: 1.5px solid #e2e8f0;
  background: #fff;
  display: flex; align-items: center; justify-content: center;
  color: #374151;
  cursor: pointer;
  transition: all 0.18s;
  flex-shrink: 0;

  &:hover:not([disabled]) {
    background: #5443ad;
    border-color: #5443ad;
    color: #fff;
    box-shadow: 0 4px 14px rgba(84,67,173,0.28);
  }

  &[disabled] {
    opacity: 0.35;
    cursor: not-allowed;
  }
}

.gp-nav-counter {
  font-size: 12px;
  font-weight: 600;
  color: #94a3b8;
  white-space: nowrap;
  margin-left: 4px;
}

/* ════════════════════════════════════════════════
   CAROUSEL
════════════════════════════════════════════════ */
.gp-carousel-outer {
  position: relative;
}

.gp-carousel-track-wrap {
  overflow: hidden;
  border-radius: 16px;
}

.gp-carousel-track {
  display: flex;
  gap: 20px;
  transition: transform 0.45s cubic-bezier(.4,0,.2,1);
  will-change: transform;
  align-items: stretch;
}

/* ════════════════════════════════════════════════
   CARDS
════════════════════════════════════════════════ */
.gp-card {
  background: #fff;
  border: 1px solid #e9eaf0;
  border-radius: 16px;
  padding: 22px 22px 18px;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  flex-shrink: 0;

  /* width controlled by JS visibleCount */
  transition: box-shadow 0.2s, transform 0.2s, border-color 0.2s;

  &:hover {
    box-shadow: 0 10px 32px rgba(84,67,173,0.12);
    transform: translateY(-3px);
    border-color: rgba(84,67,173,0.28);
  }
}

.gp-card__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.gp-card-badge {
  display: inline-flex;
  align-items: center;
  background: rgba(84,67,173,0.08);
  color: #5443ad;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 3px 9px;
  border-radius: 100px;
}

.gp-card-status {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 100px;
  background: #dcfce7;
  color: #15803d;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.gp-status-dot {
  width: 5px; height: 5px;
  border-radius: 50%;
  background: currentColor;
}

.gp-card-title {
  font-size: 15px;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.4;
  margin-bottom: 8px;
}

.gp-card-desc {
  font-size: 12.5px;
  color: #6b7280;
  line-height: 1.65;
  margin-bottom: 16px;
  flex: 1;
}

.gp-card-meta {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}

.gp-meta-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #6b7280;
}

.gp-meta-icon {
  width: 13px; height: 13px;
  color: #9ca3af;
  flex-shrink: 0;
}

.gp-card-footer {
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid #f1f1f4;
}

.gp-card-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12.5px;
  font-weight: 700;
  color: #5443ad;
  transition: gap 0.18s;
}

.gp-card:hover .gp-card-link { gap: 9px; }

/* ════════════════════════════════════════════════
   DOT INDICATORS
════════════════════════════════════════════════ */
.gp-dots {
  display: flex;
  justify-content: center;
  gap: 6px;
  margin-top: 24px;
}

.gp-dot {
  width: 8px; height: 8px;
  border-radius: 99px;
  background: #e2e8f0;
  cursor: pointer;
  transition: all 0.25s;

  &--active {
    background: #5443ad;
    width: 24px;
  }

  &:hover:not(.gp-dot--active) { background: #c4b5fd; }
}

/* ── Empty ── */
.gp-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 60px 0;
  color: #94a3b8;
  font-size: 14px;
}

/* ════════════════════════════════════════════════
   RESPONSIVE
════════════════════════════════════════════════ */
@media (max-width: 1024px) {
  .gp-inner { padding: 0 32px; }
}

@media (max-width: 768px) {
  .gp-section  { padding: 40px 0 48px; }
  .gp-inner    { padding: 0 20px; }
  .gp-header   { flex-direction: column; align-items: flex-start; gap: 16px; }
}

@media (max-width: 480px) {
  .gp-inner { padding: 0 14px; }
  .gp-title { font-size: 20px; }
}

sp_widget.script:
(function() {
  data.programs = [];
  data.error    = null;

  var gr = new GlideRecordSecure('x_enno_gatenow_grant_program');
  gr.addQuery('active', true);
  gr.addQuery('status', 'Published');
  gr.orderBy('proposal_open_date');
  gr.setLimit(50);  
  gr.query();

  while (gr.next()) {
    data.programs.push({
      sys_id:      gr.getUniqueValue(),
      program_name: gr.getDisplayValue('program_name'),
      category:    gr.getDisplayValue('category'),
      description: gr.getDisplayValue('description'),
      open_date:   gr.getDisplayValue('proposal_open_date'),
      budget:      gr.getDisplayValue('program_budget'),
      status:      gr.getDisplayValue('status')
    });
  }
})();
